	@Test
	void localDeletionRequiresPasswordOnDirectPost() throws Exception {
		String previous = System.getProperty(PROPERTY);
		System.setProperty(PROPERTY, "configured deletion password");
		DeleteServlet servlet = new DeleteServlet();
		RepositoryManager manager = mock(RepositoryManager.class);
		servlet.setRepositoryManager(manager);
		try {
			servlet.init(TestServletConfig.withParams("delete", "cookie-max-age", "300"));
			MockHttpServletRequest request = new MockHttpServletRequest("POST", "/delete");
			request.addParameter("id", "memory");
			MockHttpServletResponse response = new MockHttpServletResponse();

			servlet.service(request, response);

			assertThat(response.getStatus()).isEqualTo(403);
			assertThat(response.getRedirectedUrl()).isNull();
			verify(manager, never()).removeRepository("memory");
		} finally {
			servlet.destroy();
			if (previous == null) {
				System.clearProperty(PROPERTY);
			} else {
				System.setProperty(PROPERTY, previous);
			}
		}
	}

