	@Test
	void localHashedPolicyRequiresTheOriginalExactPassword() throws Exception {
		String verifier = "{pbkdf2-sha256}600000:AAECAwQFBgcICQoLDA0ODw==:AFwbQVv8XDCxngXh6xWwrb6tx590IMAaALe248MW164=";
		RepositoryManager manager = mock(RepositoryManager.class);
		DeleteServlet servlet = initialized(manager, verifier);
		try {
			assertThat(metadata(service(servlet, get())).path("repository-deletion-password-required").asBoolean())
					.isTrue();
			for (String supplied : new String[] { null, "wrong", verifier }) {
				assertThat(service(servlet, post(false, supplied)).getStatus()).isEqualTo(403);
			}
			verify(manager, never()).removeRepository("memory");
			MockHttpServletResponse allowed = service(servlet, post(false, "  å秘密🔒\0\t "));
			assertThat(allowed.getRedirectedUrl()).isEqualTo("../");
			assertThat(allowed.getHeaders("Set-Cookie")).noneMatch(value -> value.contains("delete-password"));
			verify(manager).removeRepository("memory");
		} finally {
			servlet.destroy();
		}
	}

