	@Test
	void nativeHtmlDenialAlsoRetainsTheDeletePageModel() throws Exception {
		RepositoryManager manager = mock(RepositoryManager.class);
		when(manager.getAllRepositoryInfos()).thenReturn(List.of(repository("memory"), repository("other")));
		DeleteServlet servlet = initialized(manager, "secret");
		try {
			MockHttpServletRequest request = post(false, "wrong");
			request.addHeader("Accept", "text/html");
			MockHttpServletResponse response = service(servlet, request);
			assertThat(response.getStatus()).isEqualTo(403);
			assertThat(response.getContentType()).startsWith("text/html");
			Matcher initialModel = Pattern.compile("data-workbench-initial-model=\"([^\"]+)\"")
					.matcher(response.getContentAsString());
			assertThat(initialModel.find()).as("HTML contains the delete page model").isTrue();
			String model = new String(Base64.getUrlDecoder().decode(initialModel.group(1)), StandardCharsets.UTF_8);
			MockHttpServletResponse decoded = new MockHttpServletResponse();
			decoded.getWriter().write(model);
			assertThat(metadata(decoded).path("repository-deletion-password-required").asBoolean()).isTrue();
			assertThat(metadata(decoded).path("selectedRepositoryId").asText()).isEqualTo("memory");
			assertThat(model).contains("memory", "other", RepositoryDeletionDeniedException.MESSAGE)
					.doesNotContain("wrong", "secret");
		} finally {
			servlet.destroy();
		}
	}

