	private static DeleteServlet initialized(RepositoryManager manager, String password, String... defaults)
			throws Exception {
		String previous = System.getProperty(PROPERTY);
		if (password == null) {
			System.clearProperty(PROPERTY);
		} else {
			System.setProperty(PROPERTY, password);
		}
		try {
			DeleteServlet servlet = new DeleteServlet();
			servlet.setRepositoryManager(manager);
			String[] parameters = new String[defaults.length + 2];
			parameters[0] = "cookie-max-age";
			parameters[1] = "300";
			System.arraycopy(defaults, 0, parameters, 2, defaults.length);
			servlet.init(TestServletConfig.withParams("delete", parameters));
			return servlet;
		} finally {
			if (previous == null) {
				System.clearProperty(PROPERTY);
			} else {
				System.setProperty(PROPERTY, previous);
			}
		}
	}

	private static MockHttpServletRequest post(boolean pageData, String password) {
		MockHttpServletRequest request = new MockHttpServletRequest("POST", "/delete");
		request.addParameter("id", "memory");
		if (password != null) {
			request.addParameter("delete-password", password);
		}
		if (pageData) {
			request.addHeader("Accept", WorkbenchPageProtocol.ACCEPT);
		}
		return request;
	}

	private static MockHttpServletRequest get() {
		MockHttpServletRequest request = new MockHttpServletRequest("GET", "/delete");
		request.addHeader("Accept", WorkbenchPageProtocol.ACCEPT);
		return request;
	}

	private static MockHttpServletResponse service(DeleteServlet servlet, MockHttpServletRequest request)
			throws Exception {
		MockHttpServletResponse response = new MockHttpServletResponse();
		servlet.service(request, response);
		return response;
	}

	private static JsonNode metadata(MockHttpServletResponse response) throws Exception {
		return response.getContentAsString()
				.lines()
				.map(JSON::readTree)
				.filter(record -> "metadata".equals(record.path("type").asText()))
				.map(record -> record.path("values"))
				.findFirst()
				.orElse(JSON.createObjectNode());
	}

	private static RepositoryInfo repository(String id) {
		RepositoryInfo info = new RepositoryInfo();
		info.setId(id);
		info.setDescription(id);
		return info;
	}
